const normalize = text => (text || "").replace(/\s+/g, " ").trim();
export function regulationExplanation(field, kind) {
  return explanations.find(row => row.kind === kind && normalize(row.original) === normalize(field?.original) && field.evidence?.some(e => e.sourceId === row.sourceId)) || null;
}
